<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use App\Services\PeriodGuard; use Carbon\Carbon;
class JournalController extends Controller {
 public function today(Request $r){$date=$r->input('date',now()->toDateString());$u=$r->user();$period=$r->attributes->get('academic_period');$q=DB::table('lesson_occurrences as l')->leftJoin('subjects as s','s.id','=','l.subject_id')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->leftJoin('rooms as rm','rm.id','=','l.room_id')->leftJoin('lesson_times as lt',fn($j)=>$j->on('lt.academic_period_id','=','l.academic_period_id')->on('lt.lesson_number','=','l.lesson_number'))->select('l.*','s.name as subject_name','g.name as group_name','rm.name as room_name','lt.starts_at','lt.ends_at')->whereDate('l.lesson_date',$date)->where('l.status','!=','cancelled');if($period)$q->where('l.academic_period_id',$period->id);if($u->hasRole('teacher')&&!$this->broad($u))$q->where('l.teacher_id',$u->teacher_id);if($u->hasRole('starosta')&&!$this->broad($u)){$gid=DB::table('students')->where('id',$u->student_id)->value('current_group_id');$q->where('l.study_group_id',$gid);}$lessons=$q->orderBy('lesson_number')->get();foreach($lessons as $x){$x->attendance_count=DB::table('attendance_records')->where('lesson_occurrence_id',$x->id)->count();$x->student_count=$this->roster($x)->count();}$d=Carbon::parse($date);return view('journal.today',['lessons'=>$lessons,'date'=>$date,'prev'=>$d->copy()->subDay()->toDateString(),'next'=>$d->copy()->addDay()->toDateString(),'today'=>now()->toDateString()]);}
 public function show(Request $r,$id){$l=$this->lesson($id);$this->authorizeLesson($r,$l,false);$students=$this->roster($l)->leftJoin('attendance_records as a',fn($j)=>$j->on('a.student_id','=','s.id')->where('a.lesson_occurrence_id','=',$l->id))->select('s.*','a.status as attendance_status','a.comment as attendance_comment')->orderBy('s.last_name')->get();$grades=DB::table('grade_records')->where('lesson_occurrence_id',$id)->get()->groupBy('student_id');return view('journal.lesson',compact('l','students','grades'));}
 public function attendance(Request $r,$id){$l=$this->lesson($id);PeriodGuard::writable($l->academic_period_id);$this->authorizeLesson($r,$l,false);abort_unless($r->user()->canDo('attendance.mark'),403);$d=$r->validate(['student_id'=>'required|exists:students,id','status'=>'required|in:present,absent,late,excused,sick']);abort_unless($this->roster($l)->where('s.id',$d['student_id'])->exists(),422);DB::table('attendance_records')->updateOrInsert(['lesson_occurrence_id'=>$id,'student_id'=>$d['student_id']],['status'=>$d['status'],'marked_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return response()->json(['ok'=>true]);}
 public function allPresent(Request $r,$id){$l=$this->lesson($id);PeriodGuard::writable($l->academic_period_id);$this->authorizeLesson($r,$l,false);abort_unless($r->user()->canDo('attendance.mark'),403);$ids=$this->roster($l)->pluck('s.id');DB::transaction(function()use($ids,$id,$r){foreach($ids as $sid)DB::table('attendance_records')->updateOrInsert(['lesson_occurrence_id'=>$id,'student_id'=>$sid],['status'=>'present','marked_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);});return response()->json(['ok'=>true,'count'=>$ids->count()]);}
 public function content(Request $r,$id){$l=$this->lesson($id);PeriodGuard::writable($l->academic_period_id);$this->authorizeLesson($r,$l,true);abort_unless($r->user()->canDo('grades.mark'),403);$d=$r->validate(['topic'=>'nullable|string|max:2000','homework'=>'nullable|string|max:4000']);DB::table('lesson_occurrences')->where('id',$id)->update(['topic'=>$d['topic']??null,'homework'=>$d['homework']??null,'updated_at'=>now()]);return back()->with('success','Тема и домашнее задание сохранены.');}
 public function grade(Request $r,$id){$l=$this->lesson($id);PeriodGuard::writable($l->academic_period_id);$this->authorizeLesson($r,$l,true);abort_unless($r->user()->canDo('grades.mark'),403);$d=$r->validate(['student_id'=>'required|exists:students,id','value'=>'required|in:2,3,4,5']);abort_unless(DB::table('students')->where('id',$d['student_id'])->where('current_group_id',$l->study_group_id)->exists(),422);$gid=DB::table('grade_records')->insertGetId(['lesson_occurrence_id'=>$id,'student_id'=>$d['student_id'],'teacher_id'=>$l->teacher_id,'value'=>$d['value'],'grade_type'=>'lesson','weight'=>1,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'id'=>$gid]);}
 private function roster($l){$q=DB::table('students as s');$has=DB::table('student_group_memberships')->where('academic_period_id',$l->academic_period_id)->where('study_group_id',$l->study_group_id)->exists();if($has)return $q->join('student_group_memberships as m','m.student_id','=','s.id')->where('m.academic_period_id',$l->academic_period_id)->where('m.study_group_id',$l->study_group_id)->where('m.status','active');return $q->where('s.current_group_id',$l->study_group_id)->where('s.status','active');}
 private function lesson($id){$l=DB::table('lesson_occurrences as l')->leftJoin('subjects as s','s.id','=','l.subject_id')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->leftJoin('teachers as t','t.id','=','l.teacher_id')->select('l.*','s.name as subject_name','g.name as group_name','t.last_name as teacher_last_name')->where('l.id',$id)->first();abort_if(!$l,404);return $l;}
 private function broad($u){return $u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic');}
 private function authorizeLesson(Request $r,$l,$grades){$u=$r->user();if($this->broad($u))return;if($u->hasRole('teacher')&&$u->teacher_id==$l->teacher_id)return;if(!$grades&&$u->hasRole('starosta')){$gid=DB::table('students')->where('id',$u->student_id)->value('current_group_id');if($gid==$l->study_group_id)return;}abort(403);}
}
